// The grab knobs (serials-library D3): seek min(60s, 10% of the probe-reported
// duration) so short files still yield a frame; a bounded per-grab deadline
// (mirrors the ffprobe/exiftool probeTimeout pattern).
const (
	defaultSeek          = 60 * time.Second
	grabTimeout          = 30 * time.Second
	seekDurationFraction = 0.1
)

// grabFrame runs `ffmpeg -nostdin -ss <seek> -i <abs> -frames:v 1 -q:v 2 -y
// <out>` (arg-slice ONLY, NEVER a shell — the paths are single arguments; a
// hostile filename cannot inject) and returns a human-readable warning on every
// soft-failure: missing binary, unwritable output, timeout, non-zero exit, or a
// zero-byte frame. An empty string means the JPEG was written. A PARENT
// cancellation is not reported here — the caller checks ctx.Err() and hard-fails
// (the only hard path; serials-library D6 soft-fail inheritance).
func grabFrame(ctx context.Context, ffmpegPath, absPath, outPath string, seek, timeout time.Duration) string {
	if _, err := exec.LookPath(ffmpegPath); err != nil {
		return "ffmpeg not found: " + ffmpegPath
	}
	if err := os.MkdirAll(filepath.Dir(outPath), 0o755); err != nil {
		return "create thumbs dir: " + err.Error()
	}
	pctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	// Arg-slice ONLY. Both paths are single arguments; never shelled out.
	cmd := exec.CommandContext(pctx, ffmpegPath,
		"-nostdin",
		"-ss", strconv.FormatFloat(seek.Seconds(), 'f', 3, 64),
		"-i", absPath,
		"-frames:v", "1",
		"-q:v", "2",
		"-y", outPath,
	)
	err := cmd.Run()
	switch {
	case ctx.Err() != nil:
		// Parent cancelled (the bounded timeout's own cancellation is
		// DeadlineExceeded, handled next); the caller converts to a hard error.
		return "grab cancelled"
	case errors.Is(pctx.Err(), context.DeadlineExceeded):
		return "ffmpeg timed out after " + timeout.String()
	case err != nil:
		return "ffmpeg exited non-zero: " + err.Error()
	}
	info, statErr := os.Stat(outPath)
	if statErr != nil || info.Size() == 0 {
		return "ffmpeg produced no frame at " + outPath
	}
	return ""
}
